import sys
from openpyxl import load_workbook

path = sys.argv[1] if len(sys.argv) > 1 else 'sales_data.xlsx'
wb = load_workbook(path)
for ws in wb.worksheets:
    print(f"=== Sheet: {ws.title} | dims: {ws.dimensions} | max_row: {ws.max_row} | max_col: {ws.max_column}")
    for row in ws.iter_rows(min_row=1, max_row=min(ws.max_row, 15)):
        vals = []
        for c in row:
            if c.value is not None:
                vals.append(f"{c.coordinate}={c.value!r}")
        if vals:
            print(" | ".join(vals))

