import openpyxl, json
wb = openpyxl.load_workbook('sales_data.xlsx')
out = {}
for ws in wb.worksheets:
    out[ws.title] = {
        'max_row': ws.max_row,
        'max_col': ws.max_column,
        'rows': [[c.coordinate, c.value] for row in ws.iter_rows() for c in row if c.value is not None][:60]
    }
print(json.dumps(out, default=str)[:4000])

